-- ============================================================================
-- IMPORT PART 1 of 3 — trainer account + 101 members
-- ============================================================================
-- SETUP first: Supabase → Authentication → Users → Add user → chayabreuer@gmail.com
--             → Send invite. Then run this whole file.
-- ============================================================================

DO $$
DECLARE
  mom_id uuid;
BEGIN
  SELECT id INTO mom_id FROM auth.users WHERE LOWER(email) = LOWER('chayabreuer@gmail.com');
  IF mom_id IS NULL THEN
    RAISE EXCEPTION 'No auth user found for chayabreuer@gmail.com. Create it in Supabase Authentication first.';
  END IF;
  DELETE FROM public.payments WHERE trainer_id = mom_id;
  DELETE FROM public.sessions WHERE trainer_id = mom_id;
  DELETE FROM public.clients WHERE trainer_id = mom_id;
  VALUES (mom_id, 'Chaya', 'Chaya''s Exercise Group', 'chayabreuer@gmail.com', 'USD', ARRAY['gym_membership'])
  ON CONFLICT (id) DO UPDATE SET
    business_name = EXCLUDED.business_name,
    template_slugs = EXCLUDED.template_slugs,
    currency = EXCLUDED.currency;
END $$;

